const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2016 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.report-row {\n  display: flex;\n  align-items: center;\n  white-space: normal;\n}\n\n.clear-storage-button .report-row {\n  margin: 0 0 0 17px;\n  display: flex;\n}\n\n.link {\n  margin-left: 10px;\n  display: none;\n}\n\n.report-row:hover .link {\n  display: inline;\n}\n\n.quota-override-editor-with-button {\n  align-items: baseline;\n  display: flex;\n}\n\n.quota-override-notification-editor {\n  border: solid 1px var(--color-details-hairline);\n  display: flex;\n  flex: auto;\n  margin-right: 4px;\n  max-width: 200px;\n  min-width: 50px;\n  min-height: 24px;\n  padding-left: 4px;\n}\n\n.quota-override-notification-editor:focus {\n  border: solid 1px var(--color-primary-variant);\n}\n\n.quota-override-error {\n  padding-top: 10px;\n  color: #f00; /* stylelint-disable-line plugin/use_theme_colors */\n  /* See: crbug.com/1152736 for color variable migration. */\n}\n\n.usage-breakdown-row {\n  min-width: fit-content;\n}\n\n.clear-storage-container {\n  overflow: auto;\n}\n\n.clear-storage-header {\n  min-width: 400px;\n}\n\n.report-content-box {\n  overflow: initial;\n}\n\n.include-third-party-cookies {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  margin-left: 16px;\n}\n\n/*# sourceURL=storageView.css */\n");export default styles;